"""Current overview, separate from immutable completed batch reports."""
import argparse
import html
import json
from pathlib import Path
from .run import write,stamp


def main():
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);a=p.parse_args();root=a.root.resolve();out=root/'outputs/short_horizon_mt5';out.mkdir(exist_ok=True)
    batches={v:json.loads((root/'outputs'/v/'results.json').read_text()) for v in ['short_horizon_mt5_v2','short_horizon_mt5_v3']}
    final=batches['short_horizon_mt5_v3'];candidate=final['challenge'][0] if final['challenge'] else None
    rows=[]
    if candidate:
        series=[('Full history · 1s delay',candidate['full_metrics']),('June–October only',candidate['metrics']),('Full history · fixed UTC+3',final['clock_stress'][0]['metrics']),('Full history · 5s delay',final['latency5'][0]['metrics'])]
        for label,metrics in series:
            for cost,m in metrics.items():
                rows.append('<tr>'+''.join(f'<td>{html.escape(str(x))}</td>' for x in [label,cost,m['trades'],f"{m['win_rate']:.2f}%",f"${m['net_pnl']:+,.2f}",f"${m['ending_balance']:,.2f}",f"{m['profit_factor']:.2f}",f"{m['drawdown_pct']:.2f}%",'FAIL'])+'</tr>')
    results_table='<div class="scroll"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in ['Period / execution','Costs','Trades','Win rate','Net P&L','Ending balance','PF','Quote drawdown','Target'])+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'
    leaders=[];names={'channel_retest':'Channel pullback','band_reentry':'Band reentry','opening_range_failure':'Opening-range failure','inside_bar_trap':'Inside-bar trap','trend_ma_reclaim':'Trend MA reclaim','rsi2_trend_reclaim':'RSI2 trend reclaim'}
    for symbol in ['NAS100','SPX500']:
        for minutes in [1,5]:
            group=[d for b in batches.values() for d in b['development'] if d['symbol']==symbol and d['minutes']==minutes]
            best=max(group,key=lambda d:d['metrics']['higher']['net_pnl']);m=best['metrics']['higher'];leaders.append('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in [symbol,f'{minutes}m',names[best['family']],best['rr'],m['trades'],f"{m['win_rate']:.2f}%",f"${m['net_pnl']:+,.2f}",f"{m['drawdown_pct']:.2f}%",'FAIL'])+'</tr>')
    leaders_table='<div class="scroll"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in ['Market','Candle','Approach','RR','Trades','Win rate','Net · higher costs','Quote drawdown','Target'])+'</tr></thead><tbody>'+''.join(leaders)+'</tbody></table></div>'
    curve=''
    if candidate:
        ledger=json.loads((root/'outputs/short_horizon_mt5_v3/ledgers/full'/f'{candidate["id"]}_standard.json').read_text());fs=ledger['fills'];values=[5000.]+[f['equity_after'] for f in fs];lo=min(values)-30;hi=max(values)+30
        points=' '.join(f'{20+i*950/(len(values)-1):.1f},{180-(v-lo)*150/(hi-lo):.1f}' for i,v in enumerate(values))
        curve=f'<svg viewBox="0 0 1000 210" role="img" aria-label="Closed-position balance for Nasdaq 5-minute channel pullback"><path d="M20 180H980" stroke="#273954"/><polyline points="{points}" fill="none" stroke="#57d8b0" stroke-width="3"/><text x="20" y="205" fill="#8298b9">December 2025</text><text x="880" y="205" fill="#8298b9">October 2026</text></svg>'
    page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trade Dashboard</title><style>
    :root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top left,#142944,#080e19 60%);color:#e4edf9;font:15px system-ui;padding:36px}main{max-width:1440px;margin:auto;animation:arrive .5s ease-out}@keyframes arrive{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}header{display:flex;justify-content:space-between;align-items:center}h1{font-size:36px;letter-spacing:-1px;margin:6px 0}h2{margin-top:34px;font-size:22px}.eyebrow{letter-spacing:2px;font-size:12px;color:#65d7c8;text-transform:uppercase}.badge{color:#8de0c7;background:#163a36;border:1px solid #26564d;border-radius:30px;padding:9px 14px}p{line-height:1.7;color:#a9b9d2;max-width:1160px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:26px 0}.card,.chart{border:1px solid #26394f;background:#101d30c9;border-radius:16px;padding:22px}.value{font-size:29px;font-weight:650;margin-top:9px;color:#fff}.muted{color:#8ea2bf;font-size:13px}.scroll{overflow:auto;border:1px solid #293951;border-radius:12px}table{border-collapse:collapse;width:100%;white-space:nowrap}th,td{text-align:left;padding:14px;border-bottom:1px solid #26354b}th{font-size:12px;color:#87cbd2;background:#14253b}td{font-variant-numeric:tabular-nums;transition:background .3s ease}tr:hover td{background:#1a2b43}a{color:#87c6ff}.warning{border-left:3px solid #e8b76e;padding:12px 18px;background:#342a1e44;color:#e8cfa7}.chart svg{width:100%;max-height:260px}.positive{color:#6fdfb5}@media(max-width:850px){body{padding:18px}.cards{grid-template-columns:repeat(2,1fr)}header{display:block}.badge{display:inline-block;margin-top:15px}}</style></head><body><main>'''
    page+='<header><div><div class="eyebrow">Separate short-horizon discovery</div><h1>Trade Dashboard</h1><p>NAS100 / SPX500 · 1m and 5m · Existing Atlas research preserved</p></div><span class="badge">PAPER ONLY · Batch complete</span></header>'
    page+='<div class="cards"><div class="card">Starting equity / isolated candidate<div class="value">$5,000</div><div class="muted">$25 maximum planned trade risk</div></div><div class="card">Development runs completed<div class="value">96</div><div class="muted">6 families · 2 markets · 2 candles · 2 RR · 2 costs</div></div><div class="card">Qualified for promotion<div class="value">0</div><div class="muted">60% win rate / below 10% drawdown gate unmet</div></div><div class="card">Available native minute history<div class="value">10½ months</div><div class="muted">Dec 12, 2025 – Oct 30, 2026</div></div></div>'
    page+='<p class="warning">The requested 12–24 months is unavailable in this MT5 archive. Older returned timestamps are hourly/daily, not valid minute history. This is reused broker-index history, not untouched validation or MNQ/MES futures data. Fees, historic broker clock, margin and fill liquidity remain uncertain.</p>'
    page+='<h2>Nasdaq 5m · Channel pullback · 1:1 RR</h2><p>The only diagnostic selection retained by the fixed selection rule. Full-period win rates are 55.00% / 52.63% at standard / higher costs. It remains a research lead and fails promotion. June–October contributed only 26 trades and a 50% win rate at either cost. Later-row drawdown includes the continuous development account; later net and win rate use later fills only.</p>'+results_table
    page+='<div class="chart" style="margin-top:20px"><div class="eyebrow">Standard costs · closed-position balance</div>'+curve+'<div class="muted">Floating quote-equity drawdown is measured separately and reported above.</div></div>'
    page+='<h2>Development leaders by market and candle</h2><p>Highest higher-cost net among the registered configurations in each group, including unprofitable failures. December 15, 2025–May 31, 2026. These rows are development diagnostics, not recommendations. Paused accounts stopped accepting entries after breaching their risk controls.</p>'+leaders_table
    page+='<h2>Execution risk retained</h2><p class="warning">A January 27 Nasdaq 1m short had $23.40 planned risk and a −$96.00 modeled realized loss. The first stop-crossing ask quote jumped above the planned stop; the replay fills at that adverse quote. No loss was clipped to the risk budget or removed. Position sizing, stops and entry pauses do not guarantee a maximum realized loss.</p>'
    page+='<h2>Evidence and next work</h2><p>Source identities, original quote copies, ledger arithmetic, lot sizing and planned-risk guards have been audited. This verifies the replay calculations under stated assumptions; it does not verify broker fills, independent profitability or the annual return objective. Preserved research hashes match. All failure ledgers and protocols remain available.</p><p>The next separate hypotheses are time-of-day volatility breakout and prior-session level reclaim. Their exact rules must be registered before financial replay. Published research supplies ideas only. No candidate can be promoted by repeatedly optimizing this same period; it needs fresh frozen prospective observations or genuine MNQ/MES history.</p>'
    page+='<p><a href="../short_horizon_mt5_v2/report.html">Initial families · complete record</a> · <a href="../short_horizon_mt5_v3/report.html">Trend families · complete record</a> · <a href="../short_horizon_mt5_v2/audit.json">Initial audit</a> · <a href="../short_horizon_mt5_v3/audit.json">Trend audit</a> · <a href="../short_horizon_mt5_v3/results.json">Metrics download</a></p>'
    page+='<p>Primary research leads: <a href="https://concretumgroup.substack.com/p/beat-the-market-with-intraday-momentum">Concretum intraday momentum</a> · <a href="https://www.newyorkfed.org/research/staff_reports/sr125.html">New York Fed support/resistance research</a>. Their instruments and rules differ from this study.</p><p class="muted">Updated '+stamp()+'</p></main></body></html>'
    (out/'index.html').write_text(page,encoding='utf-8');write(out/'current.json',dict(updated_utc=stamp(),batches=list(batches),qualified=0,paper_only=True,independently_validated=False))
    print(out/'index.html')


if __name__=='__main__':main()
